style_templates.template_json:
{
  "design_system_spec": {
    "meta": {
      "style_name": "动态语义生成 - 自适应风格规范",
      "vibe_engine": {
        "directive": "根据输入报告的行业属性、情绪词及受众，动态合成以下参数。禁止机械套用。",
        "current_archetype": "Tech_Performance_Dark (示例)",
        "logic_rationale": "识别到能源科技背景及高增长KPI，采用深色底与金色点亮，强化实验数据权威感。"
      },
      "aspect_ratio": "16:9",
      "resolution": "4K Ultra HD (3840x2160)",
      "layout_guidelines": {
        "strategy": "深色主题下避免大段文字：每页只放 1 句结论 + 3 条证据；标题尽量 10-14 字内。若必须换行，第一行放“对象/结论”，第二行放“场景/指标”。",
        "directive": "CRITICAL: Text content, especially titles, must be adapted to fit its container aesthetically. Do not rely solely on font size."
      }
    },
    "visual_dna": {
      "purpose": "直接映射给图像生成模型 (SD/Midjourney) 的提示词片段",
      "environment": "Deep navy to obsidian radial gradient, cinematic lighting, extreme high contrast",
      "texture": "Carbon fiber weave, micro-grid tech lines, subtle glowing particles",
      "lighting": "Edge lighting, amber-gold glow accents, volumetric shadows",
      "composition": "Minimalist, 16:9, wide angle, professional dashboard aesthetic, clean negative space for text."
    },
    "global_margins": {
      "scale": "6%",
      "style": "仪表盘边距",
      "purpose": "暗底中需要更紧凑的版面控制，突出图表与数字冲击力。"
    },
    "background_layer": {
      "fill_color": "#0B1020",
      "pattern": {
        "type": "gradient",
        "style": "深海军蓝到黑的径向渐变，叠加极细网格线（2%强度）",
        "purpose": "营造科技感与聚焦感，让关键数字在暗底中更醒目。"
      }
    },
    "color_palette": {
      "primary": {
        "hex": "#D6B15E",
        "semantic": "价值感、增长、决策信号",
        "usage": "关键数字、重点词、章节编号、目录序号、图表强调线/点"
      },
      "auxiliary_charting": {
        "colors": [
          "#D6B15E",
          "#2DD4BF",
          "#60A5FA",
          "#F97316"
        ],
        "logic": "金色=结论/目标；青色=性能提升；蓝色=区域/市场；橙色=风险/成本。"
      },
      "neutral": {
        "border": "#27324A",
        "divider": "#1F2A44",
        "light_bg": "#121A2E"
      },
      "text": {
        "primary": "#F3F4F6",
        "secondary": "#B7C0CE",
        "highlight": "#D6B15E",
        "on_image": "#FFFFFF"
      }
    },
    "content_processing_rules": {
      "text_conciseness": {
        "directive": "When generating titles, prioritize conciseness to fit layout constraints.",
        "action": "标题强制改为“KPI/结论 + 关键词”，示例：‘缩水控制：≤2%’、‘扩张目标：200家门店’。"
      },
      "user_input_filtering": {
        "directive": "CRITICAL: Deeply analyze user input to distinguish between content and meta-commentary.",
        "thinking_process_requirement": "Requires semantic understanding to separate intent from content. '开场强调:' is an instruction, not text.",
        "examples_to_exclude": [
          "Style guides (e.g., '(McKinsey/BCG风格)', 'Please use bullet points')",
          "Drafting notes (e.g., '[Insert figures]', '保密信息...', '数据来源...')",
          "Conversational fillers (e.g., 'Here is the text:', '核心摘要:', '首先我们看...')",
          "Internal comments (e.g., 'Note to designer: emphasize this point')",
          "Citations (e.g., [1], [2], (Author, 2024))"
        ],
        "action": "坚决剔除任何非展示性元数据；把解释性长句改成‘短语+数据’；只保留可验证数字、对比结论与关键词。"
      }
    },
    "graphic_elements": {
      "logo": {
        "protection_rule": "CRITICAL: 若用户提供了企业Logo，将其视为【不可篡改的绝对资产】（Immutable Asset）。禁止 AI 模型对其进行任何形式的“重新设计”、“二次渲染”、“风格化”或“细节脑补”（NO AI hallucination or re-rendering）。",
        "shape_and_ratio": "严格锁定原始长宽比例和几何构造，严禁拉伸、挤压、变形、替换字体或修改内部图形结构。",
        "allowed_modifications": "处理Logo时必须采用图层直接叠加（Direct Layer Overlay）机制。仅允许：1. 等比例缩放以适应容器；2. 基于背景对比度安全规则的合法整体单色化（如变为全白或全金）。"
      },
      "containers": {
        "summary_box": {
          "background": "#121A2E",
          "border": "1px solid #27324A",
          "corner_radius": "12px",
          "effect": "暗底信息面板：像仪表盘模块，适合 KPI 与关键结论。"
        }
      },
      "iconography": {
        "style": "Minimalist Linear",
        "effects": "发光描边（主色金/青），轻微外发光点题，避免多色。"
      },
      "lines_and_dividers": {
        "color": "#1F2A44",
        "style": "solid",
        "weight": "1px",
        "function": "构建科技网格分区；重点处用金色短线作强调。"
      }
    },
    "slide_templates": {
      "cover_page": {
        "layout": "Minimalist Typography",
        "background": {
          "container_type": "image_slot",
          "asset_treatment_rules": {
            "overlay": "Multiply, 35-60% opacity, 黑蓝渐变压暗覆层（上深下浅）",
            "required_adjustments": [
              {
                "type": "contrast",
                "action": "increase_slightly"
              }
            ],
            "safety_check": "若背景高亮区域与标题重叠导致对比不足则加深覆层或更换构图。"
          },
          "fallback_generation_prompt": "Dark tech texture, futuristic energy flow, carbon fiber, deep blue tones, gold sparks, left-side copy-space.",
          "user_asset_priority_rule": "CRITICAL: If a user-provided image exists, it MUST be used. DO NOT generate."
        }
      },
      "data_page": {
        "layout": "Chart Focus with Insight Sidebar/Bottom",
        "vertical_rhythm": {
          "top_headline": "15%",
          "middle_chart": "65%",
          "bottom_insight": "20%"
        },
        "elements": {
          "chart_container": "强调关键点发光；必须使用辅助图表色系。",
          "key_insight_box": {
            "style": "summary_box",
            "content": "金色小标题‘TAKEAWAY’，下含 1 句结论 + 2 条证据。"
          }
        }
      },
      "content_page": {
        "layout": "Standard Header-Content Grid (No Footer)",
        "vertical_rhythm": {
          "top_section": "20%",
          "middle_section": "80%"
        },
        "elements": {
          "content_area": "左列：结论与证据（≤4条）；右列：图示/对比卡片。",
          "title": "金色短横线 + 深色细分割线"
        }
      },
      "section_header_page": {
        "layout": "Minimalist Center Focus",
        "background": {
          "overlay": "High opacity dark overlay for pure contrast"
        },
        "elements": {
          "section_number": "PART {N} - Color: #D6B15E"
        }
      },
      "toc_page": {
        "layout": "Standard List",
        "elements": {
          "list_item": "编号列表，左侧金色序号，右侧白色条目，可带一行灰色短注释"
        }
      },
      "quote_page": {
        "layout": "Minimalist Centered Typography",
        "elements": {
          "quote_text": "Huge (48-60pt), Center Aligned, Primary Text Color"
        }
      },
      "closing_page": {
        "layout": "Centered Closing",
        "elements": {
          "final_message": "Q&A",
          "slogan": "引领能源跃迁，驱动无界未来"
        }
      }
    },
    "typography_rules": {
      "font_family": "HarmonyOS Sans SC, 思源黑体 SC, PingFang SC, Arial, sans-serif",
      "hierarchy": {
        "cover_title": {
          "size": "Huge (54-64pt)",
          "weight": "ExtraBold",
          "line_break": "Semantic only"
        },
        "slide_title": {
          "size": "Large (36-44pt)",
          "weight": "Bold",
          "overflow_rule": "优先改为短标题，拒绝缩小字号导致视觉虚弱。"
        },
        "section_header": {
          "size": "Medium (22-26pt)",
          "weight": "Bold",
          "max_lines": 1
        },
        "body_text": {
          "size": "Small (14-16pt)",
          "weight": "Regular",
          "line_height": "1.6"
        }
      }
    }
  }
}
